import java.util.*;

public class Solution {
    static class Edge {
        int to, weight;
        Edge(int t, int w) { this.to = t; this.weight = w; }
    }
    static class Node implements Comparable<Node> {
        int id; long dist;
        Node(int i, long d) { this.id = i; this.dist = d; }
        public int compareTo(Node o) { return Long.compare(this.dist, o.dist); }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int v = sc.nextInt();
        int e = sc.nextInt();
        List<List<Edge>> adj = new ArrayList<>();
        for (int i = 0; i < v; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt();
            int to = sc.nextInt();
            int w = sc.nextInt();
            adj.get(u).add(new Edge(to, w));
        }
        int s = sc.nextInt();
        long[] dist = new long[v];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[s] = 0;
        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.add(new Node(s, 0));
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.dist > dist[cur.id]) continue;
            for (Edge edge : adj.get(cur.id)) {
                if (dist[cur.id] + edge.weight < dist[edge.to]) {
                    dist[edge.to] = dist[cur.id] + edge.weight;
                    pq.add(new Node(edge.to, dist[edge.to]));
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < v; i++) {
            sb.append(dist[i] == Long.MAX_VALUE ? "-1" : dist[i]).append(i == v - 1 ? "" : " ");
        }
        System.out.println(sb.toString());
    }
}

