#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define INF 1000000000000LL

typedef struct Edge { int to; long long w; struct Edge *next; } Edge;

int main() {
    int v, e;
    if (scanf("%d %d", &v, &e) != 2) return 0;
    Edge **head = (Edge**)calloc(v, sizeof(Edge*));
    for (int i = 0; i < e; i++) {
        int u, to;
        long long w;
        scanf("%d %d %lld", &u, &to, &w);
        Edge *edge = (Edge*)malloc(sizeof(Edge));
        edge->to = to; edge->w = w; edge->next = head[u]; head[u] = edge;
    }
    int s;
    scanf("%d", &s);
    long long *dist = (long long*)malloc(v * sizeof(long long));
    bool *visited = (bool*)calloc(v, sizeof(bool));
    for (int i = 0; i < v; i++) dist[i] = INF;
    dist[s] = 0;

    for (int i = 0; i < v; i++) {
        int u = -1;
        for (int j = 0; j < v; j++) {
            if (!visited[j] && (u == -1 || dist[j] < dist[u])) u = j;
        }
        if (u == -1 || dist[u] == INF) break;
        visited[u] = true;
        for (Edge *p = head[u]; p != NULL; p = p->next) {
            if (dist[u] + p->w < dist[p->to]) {
                dist[p->to] = dist[u] + p->w;
            }
        }
    }
    for (int i = 0; i < v; i++) {
        if (dist[i] == INF) printf("-1%s", (i == v - 1) ? "\n" : " ");
        else printf("%lld%s", dist[i], (i == v - 1) ? "\n" : " ");
    }
    return 0;
}
